function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectives = words.filter(word => adjectiveDetector(word)); // Utilize a helper function (see below)
  if (adjectives.length >= 2) {
    const swapped = [...words]; // Create a mutable copy of the words array
    swapped.splice(words.indexOf(adjectives[0]), 1, adjectives[1]);  // Swap positions
    swapped.splice(words.indexOf(adjectives[1]), 1, adjectives[0]);
    return swapped.join(' '); 
  } else {
    return sentence; // No sufficient adjectives to swap
  }
}

// Helper function (adjective detection - refine as needed for accuracy)
function adjectiveDetector(word) {
  //  Basic regex for common adjective patterns, expand for robustness
  return /^[a-zA-Z]+(?:-[a-zA-Z]+)?(ly)?$/i.test(word); 
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
