#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
pair<int, int> fibonacci(int prev1, int prev2, int n) {
    if (n <= 0) {
        return make_pair(prev1, prev2); // Base case: return initial values for n=0 or less
    } else if (n == 1) {
        return make_pair(prev2, prev1 + prev2); // Base case: next element is sum of previous two
    } else {
        auto nextPair = fibonacci(prev2, prev1 + prev2, n - 1); 
        return nextPair; // Recursively calculate and return the pair
    }
}

int main() {
    int num1, num2, count;
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2)) {  // Input validation: Ensure numeric input
        cout << "Invalid input. Please enter two integers: ";
        cin.clear(); // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid characters
    }
    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {  // Validate count as positive integer
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    // Generate and display the sequence
    auto [start, _] = fibonacci(num1, num2, 1); // Initialize with given values
    cout << start;  // Output the first element (already handled in fibonacci)
    for (int i = 2; i < count; ++i) {
        auto nextPair = fibonacci(num2, start + num2, i);
        cout << ", " << nextPair.first; // Output subsequent elements
        start = nextPair.first;  // Update 'start' for next iteration
    }
    cout << endl;

    return 0;
}
```

