```javascript
import { Injectable } from '@nestjs/common';
import { AuthGuard, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { USER_ROLES } from './constants'; // Assuming constants file for role definitions

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    const user = context.switchToHttp().getRequest().user; 

    if (!user || !user.role) return false; 

    return requiredRoles?.some(role => USER_ROLES.includes(role) && user.role === role);
  }
}

// Example Permission Array (in a dedicated services/permissions.service.ts and imported)
export const PERMISSIONS = [
  'CREATE_ARTICLE',
  'READ_ARTICLE',
  'UPDATE_ARTICLE',
  'DELETE_ARTICLE',
  'MANAGE_USERS', // Add more permission names...
];
```

**Explanation (for context, NOT to be included in final `index.js`):**

1. **`RolesGuard`:** A custom guard using `@nestjs/common`  to control access based on declared roles.
   - Retrieves `requiredRoles` from method decorators (`@UseGuards(RolesGuard(/* ... */))`).
   - Checks if the authenticated user (`context.switchToHttp().getRequest().user`) has a matching role against the required ones.
2. **`USER_ROLES` (Constants File):**  A centralized place (like `constants.ts`)  to define role enums or strings for clarity and maintainability.  This aligns with best practices.
3. **`PERMISSIONS` Array:**  Holds a comprehensive list of permission names used for finer-grained authorization logic (which can be integrated with `RolesGuard` for more complex scenarios in future expansions).


