```javascript
import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { User } from '@prisma/client';

@Injectable()
export class RoleBasedAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector, private prisma: PrismaService) { super(); }

  asynccanActivate(context): Promise<boolean | undefined> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    const user = context.switchToHttp().getRequest().user as User;
    if (!user || !requiredRoles) return false;
    const userRoles = await this.prisma.userRole.findMany({ where: { userId: user.id } });
    return requiredRoles.some(role => userRoles.some(userRole => userRole.roleId === role));
  }
}

// Example Permissions (Array format in config/permissions.ts or similar)
export const PERMISSIONS = [
  'READ_USERS', 'CREATE_USERS', 'UPDATE_USERS', 'DELETE_USERS',
  'READ_PRODUCTS', 'CREATE_PRODUCTS', 'MANAGE_ inventario', 'ANALYTICS_ACCESS',
  // ...more permissions...
];
```

**Explanation (for understanding, NOT part of the merged file):**

1. **`RoleBasedAuthGuard`:** A custom AuthGuard leveraging JWT authentication (`@nestjs/passport`) and extending NestJS's base implementation.
2. **Dynamic Role Check:**  It extracts `requiredRoles` metadata from controller methods using `@nestjs/core`'s `Reflector`. During execution, it compares these against the logged-in user's roles fetched from the database (using `PrismaService` and a `userRole` model).
3. **Permissions Array (`PERMISSIONS`):**  This  demonstrates the structured format  holding permission names as strings. In a real setup, load these from a configuration file or dedicated permission management service for flexibility.
4. **Integration:** This combined structure allows granular access control in controllers by decorating methods with  `@UseGuards(RoleBasedAuthGuard({ roles: ['ADMIN', 'EDITOR'] }))`  to enforce specific role requirements. 


