import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { TYPEORM_ROLE_PERMISSIONS } from './constants';
import { InjectRepository } from '@nestjs/typeorm';
import { UserEntity } from './user.entity';
import { Repository } from 'typeorm';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, @InjectRepository(UserEntity) private userRepository: Repository<UserEntity>) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>(TYPEORM_ROLE_PERMISSIONS, context.getHandler());
    if (!requiredRoles) return true; 

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user) throw new UnauthorizedException('Unauthorized');

    const userRoles = await this.userRepository.findOne({ id: user.id }).then(user => user.roles);
    return requiredRoles.some(role => userRoles.includes(role));
  }
}

// Example Permission Array (within app config or separate service for dynamic management)
export const ALLOWED_PERMISSIONS: string[] = [
  'CREATE_ARTICLE', 'EDIT_ARTICLE', 'DELETE_ARTICLE', 'READ_FINANCE_DATA', 'MANAGE_USERS'
];
``` 


