function geocodePlaceNames(spreadsheetId, sheetName, placeColumnName, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names from Column
  const dataRange = sheet.getRange(placeColumnName); // Assuming your place names are in A column, adjust as needed
  const placeNames = dataRange.getValues().map(row => row[0]); // Extract place names from each row

  // 3. Geocoding Loop (Using Google Maps Places API - Requires API Key Setup)
  const apiKey = 'YOUR_GOOGLE_MAPS_API_KEY'; //  Replace with your actual API key!
  for (let i = 0; i < placeNames.length; i++) {
    const placeName = placeNames[i];
    const geocoder = new google.maps.Geocoder();
    geocoder.geocode({ address: placeName }, (results, status) => {
      if (status === google.maps.GeocoderStatus.OK) {
        const latitude = results[0].geometry.location.lat();
        const longitude = results[0].geometry.location.lng();

        // 4. Update Spreadsheet Cells
        const row = i + 1; // Adjust row number based on header row
        sheet.getRange(row, latColumn).setValue(latitude);
        sheet.getRange(row, lngColumn).setValue(longitude);
        Logger.log(`Geocoded ${placeName} - Lat: ${latitude}, Lng: ${longitude}`);
      } else {
        Logger.log(`Error geocoding ${placeName}: ${status}`);
        // Handle geocoding failures (e.g., invalid address, API limits)
      }
    });
  }
}
