function geocodeAndStore(spreadsheetId, sheetName, placeColumnName, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names and Populate Data Range
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  const placeColumnIdx = values[0].indexOf(placeColumnName); // Find index of your place name column

  // 3. Google Maps Geocoding API (Requires API Key Setup!)
  const urlTemplate = "https://maps.googleapis.com/maps/api/geocode/json?address={place}&key={YOUR_API_KEY}";  // Replace {YOUR_API_KEY} with your actual Google Maps API key

  for (let row = 1; row < values.length; row++) {  // Start from row 1 (assuming headers are in row 0)
    const placeName = values[row][placeColumnIdx];
    if (placeName) {  // Only geocode if there's a place name
      const geocodeUrl = urlTemplate.replace("{place}", encodeURIComponent(placeName)).replace("{YOUR_API_KEY}", ScriptApp.Properties.getProperty('GOOGLE_MAPS_API_KEY')); // Secure API key handling
      const response = UrlFetchApp.fetch(geocodeUrl);
      const jsonData = JSON.parse(response.getContentText());

      if (jsonData.results && jsonData.results.length > 0) {
        const location = jsonData.results[0].geometry.location;
        sheet.getRange(row, latColumn).setValue(location.lat);
        sheet.getRange(row, lngColumn).setValue(location.lng);
      } else {
        // Handle cases where no geocoding result is found (e.g., log an error or placeholder value)
        Logger.log(`No geocode found for: ${placeName}`); 
        sheet.getRange(row, latColumn).setValue("Not Found"); // Or your preferred handling
        sheet.getRange(row, lngColumn).setValue(""); 
      }
    }
  }
}
