/**
 * Searches for a place name in a specified column and retrieves latitude/longitude, storing them in designated columns.
 *
 * @param {string} sheetName The name of the Google Sheet containing the data.
 * @param {number} placeNameColumn The index (A=1, B=2, etc.) of the column with place names.
 * @param {number} latColumn The index where latitude values will be stored.
 * @param {number} lngColumn The index where longitude values will be stored.
 * @param {string} apiKey Your Google Maps Geocoding API key (obtain from https://developers.google.com/maps/documentation/geocoding/get-api-key)
 */
function geocodeAndPopulate(sheetName, placeNameColumn, latColumn, lngColumn, apiKey) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const lastRow = sheet.getLastRow(); 

  // Iterate through each row containing a place name
  for (let row = 2; row <= lastRow; row++) { // Start from row 2, assuming header row is row 1
    const placeName = sheet.getRange(row, placeNameColumn).getValue();
    if (placeName) {  // Only process if a place name exists

      const geocoder = new google.maps.Geocoder();
      const request = { address: placeName };
      geocoder.geocode(request, (results, status) => {
        if (status === 'OK' && results.length > 0) {
          const latitude = results[0].geometry.location.lat();
          const longitude = results[0].geometry.location.lng();

          // Store lat/long in respective columns
          sheet.getRange(row, latColumn).setValue(latitude);
          sheet.getRange(row, lngColumn).setValue(longitude);
        } else {
          // Handle geocoding errors (e.g., place not found)
          Logger.log(`Error geocoding "${placeName}" : ${status}`);
          sheet.getRange(row, latColumn).setValue("Geocoding Error"); // or desired error indicator
          sheet.getRange(row, lngColumn).setValue(""); 
        }
      });
    }

