    public AudioSource audioSource; // Drag your AudioClip here in the Inspector
    public Image[] bars;          // Array of UI Image components representing visualization bars
    public float barHeightMultiplier = 5f;  // Adjust for visual intensity

    private float[] spectrumData; // To store FFT data
    private int fftSize = 256;      // Optimal FFT size for decent resolution

    void Start()
    {
        // Ensure AudioSource is set and ready
        if (!audioSource)
        {
            Debug.LogError("AudioSource not assigned in Inspector! Assign your AudioClip source.");
            return;
        }

        spectrumData = new float[fftSize]; // Initialize FFT buffer
        audioSource.clip.LoadAudioData(); // Preload audio for smoother analysis
    }

    void Update()
    {
        // 1. Fetch FFT Data
        audioSource.GetSpectrumData(spectrumData, 0, FFTWindow.Blackman); 

        // 2. Visualize Spectrum (Mapping to Bars)
        for (int i = 0; i < bars.Length && i < fftSize; i++)
        {
            float normalizedFrequency = spectrumData[i] * barHeightMultiplier; // Scale for visualization
            bars[i].fillAmount = normalizedFrequency; // Update bar fill amount
        }
    }
}
```

