```C#
using Newtonsoft.Json; // Ensure you have Newtonsoft.Json NuGet package installed

public class ImmigrationData
{
    public int VisasIssued { get; set; }
    public Dictionary<string, int> TopImmigrantCountries { get; set; }
    public List<PolicyChange> PolicyChanges { get; set; }
}

public class PolicyChange
{
    public string date { get; set; }
    public string description { get; set; }
}

public class VisaDataExtractor
{
    public static void AnalyzeJSON(string jsonString)
    {
        // 1. Deserialize JSON into C# object
        var data = JsonConvert.DeserializeObject<ImmigrationData>(jsonString);

        // 2. Extract Required Information:
        Console.WriteLine($"Visas Issued in 2021: {data.VisasIssued}");

        // Top Countries (sorted by count in descending order)
        var sortedCountries = data.TopImmigrantCountries
            .OrderByDescending(x => x.Value)
            .Take(3) // Get top 3 for brevity
            .ToDictionary(x => x.Key, x => x.Value);
        Console.WriteLine("Top 3 Immigrant Countries (and counts):");
        foreach (var country in sortedCountries)
        {
            Console.WriteLine($"{country.Key}: {country.Value}");
        }

        // Recent Policy Changes (focus on latest ones)
        Console.WriteLine("\nRecent Policy Changes:");
        foreach (var change in data.PolicyChanges.OrderByDescending(p => p.date))
        {
            Console.WriteLine($"{change.date} - {change.description}");
        }
    }
}

public static void Main(string[] args)
{
    // Replace with your actual JSON data loading mechanism
    string jsonContent = @"{ ... your provided JSON ... }"; 
    VisaDataExtractor.AnalyzeJSON(jsonContent);
}
```

