#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* argvToCString(int argc, char **argv) {
    // 1. Calculate required size: Account for all arguments plus null terminator
    size_t totalSize = 0;
    for (int i = 0; i < argc; i++) {
        totalSize += strlen(argv[i]) + 1; // +1 for separating null characters
    }
    totalSize += 1; // Extra null terminator at the end

    // 2. Allocate memory for the concatenated string
    char *result = malloc(totalSize);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1); // Handle error gracefully
    }

    // 3. Construct the c-string by joining arguments
    char *currentPos = result;
    for (int i = 0; i < argc; i++) {
        strcpy(currentPos, argv[i]);
        currentPos += strlen(argv[i]);
