import { Injectable, MiddlewareFunction, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvCheckMiddlewareDecorator {
  decorate(envCheck: boolean): MiddlewareFunction {
    return (context: ExecutionContext) => {
      const nodeEnv = process.env.NODE_ENV; 
      // Weighted emphasis on helpfulness by clearly explaining the logic:
