import { Injectable, MiddlewareFn, NestMiddleware } from '@nestjs/common';

@Injectable()
export class EnvConditionalMiddleware implements NestMiddleware {
  use(req: any, res: any, next: MiddlewareFn) {
    const envValue = process.env.NODE_ENV; 
    const proceed = envValue === 'true' || envValue === true; // lenient comparison for 'true'

    if (proceed) {
      next(); // Call next middleware/route handler in production or development (when NODE_ENV is truthy)
    } else {
      res.status(503).send('Service temporarily unavailable (NODE_ENV condition not met)'); // Controlled "false" response
    }
  }
}
```

