While TypeScript decorators directly on routes/controllers aren't *

```typescript
import { Injectable, ExecutionContext, CallHandler } from '@nestjs/common';

@Injectable()
export class EnvConditionalMiddlewareDecorator {
  private readonly envKey = 'NODE_ENV';

  constructor() {}

  decorate(target: any, propertyKey: string | symbol, descriptor: PropertyDescriptor): PropertyDescriptor {
    const originalMethod = descriptor.value;

    descriptor.value = async (ctx: ExecutionContext, next: CallHandler) => {
      const envValue = process.env[this.envKey];
      const proceed = envValue && envValue.toLowerCase() === 'true'; // Case-insensitive check

      if (proceed) {
        return next.handle(); // Call next middleware/route handler
      } else {
        return false; // Short-circuit execution
      }
    };

    return descriptor;
  }
}

// Usage Example:

// Assuming you have a middleware function named 'mySpecialMiddleware'
@Injectable()
export class MyMiddleware {
  @EnvConditionalMiddlewareDecorator() 
  async mySpecialMiddleware(ctx: ExecutionContext, next: CallHandler) {
    // Your specialized logic (executed only in 'true' NODE_ENV)
    console.log('MySpecialMiddleware executed (NODE_ENV is true)');
    return next.handle(); 
  }
