        {"tall", "reaching skyward"}, {"solitude", "silent grace"} //  Thematic additions
    };

    public static string CreateHaiku(string FocusWord = "tree")
    {
        Random rand = new Random();
        List<string> lines = new List<string>();

        // Line 1: Setting & Focus
        lines.Add($"{NatureWords["meadow"]} where {NatureWords[FocusWord]} {NatureWords["tall"]} stands");

        // Line 2: Sensory Detail & Emotion
        lines.Add($"{NatureWords["mist"]}  embraces boughs, a whisper of {NatureWords["solitude"]}");

        // Line 3: Contemplative End
        lines.Add("Ancient wisdom breathes, in silence, ever green"); 

        return string.Join(Environment.NewLine, lines);
    }
}

