public class HaikuGenerator
{
    private static readonly Dictionary<string, string[]> _wordBanks = new Dictionary<string, string[]>
    {
        {"Nature", new[] {"mist-wreathed", "ancient boughs", "sun-kissed leaves", "silent vigil", "emerald glade"}},
        {"Solitude", new[] {"standing lone", "windswept grace", "thoughts unfold", "world fades away", "unyielding strength"}},
        {"Imagery", new[] {"silver veil", "meadow sighs", "whispers soft", "dawn's gentle touch", "sky's embrace"}}
    };

    public static string GenerateHaiku(string themeEmphasis = "Nature")
    {
        Random rand = new Random();
        List<string> lines = new List<string>();

        // Line 1 (5 Syllables - Nature Focus)
        lines.Add($"{_wordBanks[themeEmphasis][rand.Next( _wordBanks[themeEmphasis].Length)]} tree");

        // Line 2 (7 Syllables - Solitude Blend)
        lines.Add($"{_wordBanks["Solitude"][rand.Next(_wordBanks["Solitude"].Length)]}, meadow hushed");

        // Line 3 (5 Syllables - Imagery Touch)
        lines.Add($"{_wordBanks["Imagery"][rand.Next(_wordBanks["Imagery"].Length)]}");

        return string.Join("\n", lines);
    }
}

