import React, { useState, useRef } from 'react';
import useCombobox from 'downshift/useCombobox';
import { searchEmails } from './emailService'; // Assuming your async function resides here

const EmailAutocomplete = () => {
  const [inputValue, setInputValue] = useState('');
  const dropdownRef = useRef(null); // For manual focus management (optional but helpful)

  const {
    isOpen,
    onInputValueChange,
    getProps,
    selectedItem,
    highlightedIndex,
    clearSelection,
  } = useCombobox({
    items: [], // Initially empty, populated dynamically
    onInputValueChange({ value }) {
      setInputValue(value);
      // Trigger email search on every change
      searchEmails(value)
        .then(emails => {
          dropdownRef.current.setState({ items: emails }); 
        })
        .catch(error => console.error('Email search error:', error));
    },
    itemToString: (email) => email, // Display email as-is
    selectedItem: selectedItem ? selectedItem : '', // Manage selected item state
    onKeyDown({ key }) {
      if (key === 'ArrowDown' && !isOpen) dropdownRef.current.open(); // Open dropdown on Down arrow
      // ... handle other key events as needed
    },
  });

  const handleSelect = (selectedEmail) => {
    setInputValue(selectedEmail); // Update input with chosen email
    clearSelection(); // Clear dropdown selection after pick
  };

  return (
    <div>
      <input 
        {...getProps({
          placeholder: 'Enter email address',
          value: inputValue, // Bind input value
          onChange: onInputValueChange // Leverage Downshift's onChange
        })}
        ref={dropdownRef} // Provide ref for manual dropdown control (optional)
      />
      {isOpen && (
        <ul className="downshift-menu">
          {dropdownRef.current.state.items.map((email, index) => (
            <li 
              key={email} 
              className={highlightedIndex === index ? 'highlighted' : ''}
              onClick={() => handleSelect(email)}
            >
              {email}
            </li>
          ))}

