export default function Library({ setInputMessage }: { setInputMessage: Dispatch }) {
  const utils = api.useContext();
  const [selectedTargetPrompt, setSelectedTargetPrompt] = useState('');
  const [editedName, setEditedName] = useState('');
  const [editedPrompt, setEditedPrompt] = useState('');

  // Combine prompt fetching and sorting for efficiency
  const { data: prompts, refetch: refreshPrompts } = api.prompt.all.useQuery(
    {}, // Empty dependency array ensures refetch on necessary updates
    { sort: (a, b) => b.updatedAt.getTime() - a.updatedAt.getTime() } // Sort directly within query
  );

  const { isOpen, onOpen, onClose } = useDisclosure();
  const upsertPrompt = api.prompt.upsert.useMutation(onSuccess => refreshPrompts(), { // Refetch on success
    onSuccess: utils.prompt.invalidate,
  });
  const deletePrompt = api.prompt.delete.useMutation(onSuccess => refreshPrompts(), { // Refetch on success
    onSuccess: utils.prompt.invalidate,
  });

  return (
    <>
      {/* ... (Button logic for adding new prompt remains similar) */}

      <ul>
        {prompts.map(p => (
          <li 
            key={p.id} // Ensure unique keys for list items
            variant="ghost" 
            alignSelf={"flex-end"}
            onClick={() => {
              setSelectedTargetPrompt(p.id);
              setEditedPrompt(p.prompt);
              setEditedName(p.name);
              onOpen();
            }}
          >
            {p.name} - {p.prompt} 
          </li>
        ))}
      </ul>

      {/* ... (Edit/Delete modal and their actions improved for clarity) */}
      <Dialog {...{ isOpen, onOpen, onClose }} maxWidth="xs">
        <DialogTitle>{selectedTargetPrompt === "" ? "New" : "Edit"} Prompt</DialogTitle>
        <DialogContent>
          <TextField 
            label="Name" 
            value={editedName} 
            onChange={e => setEditedName(e.target.value)} 
            fullWidth 
            margin="dense"
            autoFocus
          />

