using Accord.MachineLearning;
using Accord.MachineLearning.Bayes;
using Accord.NLP;
using System;
using System.Collections.Generic;

public class NaiveBayesTextClassifier
{
    public static void Main(string[] args)
    {
        // 1. Prepare Dataset (Simulated for brevity, replace with your real labeled data)
        var dataset = new List<Tuple<string, string>>
        {
            // Sports examples
            Tuple.Create("The sports game was thrilling", "Sports"),
            Tuple.Create("Tennis match underway", "Sports"),
            // Politics examples... (similar format)
            // Entertainment examples... (similar format)
        };

        // 2. Feature Extraction with CountVectorizer
        var vectorizer = new CountVectorizer();
        var featureMatrix = vectorizer.Transform(dataset.Select(x => x.Item1).ToArray());

        // 3. Label Encoding (Accord handles this internally with NaiveBayes)
        var labels = dataset.Select(x => x.Item2).ToArray();

        // 4. Train Naive Bayes Model
        var naiveBayes = new NaiveBayes<string>(featureMatrix, labels);
        naiveBayes.Train();

        // 5. Conditional Probability Calculation (Implicit in trained model)
        //   -  `naiveBayes.PosteriorProbabilities`  holds category probabilities *given* features of a sample.

        // 6. Classification - New Sentence Prediction
        string newSentence = "The sports game was exciting";
        var transformedSentence = vectorizer.Transform(new string[] { newSentence });
        var predictions = naiveBayes.Decide(transformedSentence); // Returns predicted category
        Console.WriteLine($"Predicted Label for '{newSentence}': {predictions[0]}"); 
    }
}
```

