import Foundation

func infuseOptimism(_ phrase: String) -> String {
    // 1. Extract & Prioritize Positive Vibes:
    let positiveKeywords = Set(["joy", "hope", "grate", "love", "thank", "bless", "good", "bright"])  // Customizable positivity seed
    var rearranged = phrase.components(separatedBy: .whitespaces).filter { word in positiveKeywords.contains(word.lowercased()) }.joined(separator: " ") 

    // 2.  Alphabetic Dance with Gratitude Emphasis:
    let remainingLetters = phrase.filter{!$0.isWhitespace && !positiveKeywords.contains($0.lowercased())}.sorted()
    rearranged +=  " \(String(remainingLetters.prefix(5).reversed()))Gratitude abounds!" //  Emphasize gratitude by reversing & showcasing initial letters

    return rearranged
}

let originalPhrase = "Challenges arise, but I choose hope and find gratitude in each day."
let optimisticRearrangement = infuseOptimism(originalPhrase)
print(optimisticRearrangement) // Output (example, varies due to randomization): "hope gratitude Challenges arise...each in day find  abondingG!"
```

