function Check-RestrictedACLs {
    param(
        [string]$FolderPath,
        [string]$DomainName = (Get-ADDomain).Name  # Default to current domain
    )

    # Get all users and groups in the domain for SIDHistory comparison
    $DomainUsersAndGroups = Get-ADUser -Filter * -Properties SamAccountName,SIDHistory -Properties * | ForEach-Object { $_.SamAccountName, $_.SIDHistory }
    $DomainUsersAndGroups += Get-ADGroup -Filter * -Properties SamAccountName,SIDHistory -Properties * | ForEach-Object { $_.SamAccountName, $_.SIDHistory }

    # Recursive function to traverse folders and analyze ACLs
    function Recurse-FolderACLs {
        param(
            [string]$CurrentPath
        )
        Get-ChildItem -Path $CurrentPath -Recurse | ForEach-Object {
            # Analyze ACLs of each item (folder/file)
            $AclEntries = Get-Acl $_.FullName
            foreach ($Entry in $AclEntries.Access) {
                # Extract SIDs from ACL entries
                $AclSid = $Entry.IdentityReference.Translate([System.Security.Principal.NTAccount]) -as [System.Security.Principal.SecurityIdentifier]

                # Check if SID exists ONLY in Domain Users/Groups' SIDHistory
                $FoundInHistory = $false
                foreach ([string]$User, $Histories in $DomainUsersAndGroups) {
                    if ($Histories -contains $AclSid.ToString()) {
                        $FoundInHistory = $true; break
                    }
                }

                # If SID found ONLY in history, flag as potentially restricted
                if ($FoundInHistory) {
                    Write-Warning "Potential Restricted ACL: Folder - $($_.FullName), User/Group SID: $($AclSid.Value) found ONLY in SIDHistory of $($User)"
                }
            }

            # Recursively process subfolders
            if (-not $_.PSIsContainer) { Continue }  # Skip files, process only folders
            Recurse-FolderACLs -CurrentPath $_.FullName
        }
    }

