# Define function to recursively check folders and ACLs against SIDHistory
function Check-FolderACLsWithSIDHistory {
    param(
        [string]$Path,
        [string]$DomainController = (Get-ADDomainController).Name # Default to current domain controller
    )

    # Get all users and groups in the domain for SIDHistory lookup
    $DomainUsersAndGroups = Get-ADUser -Filter * -Properties SamAccountName,SidHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SidHistory }
    $DomainUsersAndGroups += Get-ADGroup -Filter * -Properties SamAccountName,SidHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SidHistory }

    # Recursive function to process folders
    function Process-Folder {
        param(
            [string]$FolderLocation
        )
        # Get ACL entries for the folder
        $ACL = Get-Acl -Path $FolderLocation

        # Iterate through each Access Control Entry (ACE)
        foreach ($ACE in $ACL.Access) {
            # Extract SID from the ACE
            $SID = $ACE.IdentityReference.Translate($DomainController)

            # Check if SID exists ONLY in someone's SIDHistory within the domain
            $FoundInHistory = $false
            foreach ($UserOrGroup in $DomainUsersAndGroups) {
                if ($UserOrGroup.SidHistory -contains $SID) {
                    $FoundInHistory = $true; break
                }
            }

            # If SID found ONLY in history, report and log (adjust logging as needed)
            if ($FoundInHistory) {
                Write-Output "WARNING: Folder '$FolderLocation' contains ACE with SID $($SID.Value) found ONLY in SIDHistory of domain entity $($UserOrGroup.SamAccountName)"
                # Add more detailed logging to a file or event log here...
            }
        }

        # Recursively process subfolders
        Get-ChildItem -Path $FolderLocation -Recurse | ForEach-Object { Process-Folder -FolderLocation $_.FullName }
    }

    # Start recursive processing from provided path
    Process-Folder -FolderLocation $Path
}

# Example Usage:
Check-FolderACLsWithSIDHistory -Path "C:\SensitiveData\" 
```

