# Define function to recursively check folders and ACL SIDs against SIDHistory
function Check-RecursiveACLs {
    param(
        [string]$FolderPath,
        [string]$DomainController = (Get-ADDomainController).Name
    )

    # Get all users and groups in the domain with SIDHistory
    $DomainUsersAndGroups = Get-ADUser -Filter * -Properties SamAccountName,SIDHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SIDHistory }
    $DomainUsersAndGroups += Get-ADGroup -Filter * -Properties SamAccountName,SIDHistory -Server $DomainController | ForEach-Object { $_.SamAccountName, $_.SIDHistory }

    # Process each folder and subfolder recursively
    Get-ChildItem -Path $FolderPath -Recurse | ForEach-Object {
        $Acl = Get-Acl $_.FullName

        # Analyze each Access Control Entry (ACE) in the ACL
        $RestrictedSids = @()
        foreach ($Ace in $Acl.Access) {
            if ($Ace.IdentityReference -isnot Nothing) {
                $Sid = $Ace.IdentityReference.Translate([System.Security.Principal.NTAccount])
                if (!(Get-Member -InputObject $DomainUsersAndGroups -Name SamAccountName -ErrorAction SilentlyContinue | Where-Object {$_.SamAccountName -like "*$($Sid.Value)*" -and $_.SIDHistory -contains $Sid.Value})) {
                    $RestrictedSids += $Sid.Value # Add SIDs not found in SIDHistory
                }
            }
        }

        # Report findings for the current folder
        if ($RestrictedSids.Count -gt 0) {
            Write-Output "Folder: $($_.FullName) contains ACL SIDs NOT present in any user/group's SIDHistory:"
            $RestrictedSids | ForEach-Object { Write-Output "- $($_.ToString())" }
            Write-Output "" # Separator between folder reports
        }
    }
}

# Example Usage: Start checking from 'C:\MyDataFolder' and specify your domain controller if needed
Check-RecursiveACLs -FolderPath "C:\MyDataFolder" -DomainController "yourDCname.domain.com" 
```

